<?php
/** TEMP PS S1615 run e1e — D: deploy darbalaukis v3.18.1 (5 b64 dalys: 4 iš ps-backups + likutis, kiekvienos dalies md5 + bendras md5 + token_get_all, gyvo failo sargas v3.18). T (naujas procesas, testuotojas): versija/md5; loopback HTML Surinkti AV — #35438 2 stulpelis (turi būti be jau išsiųstos Animonda eilutės, „1 vnt.“); Visi — #35421 2 stulpelis (be atšauktos Prins eilutės); Playwright shots. */
add_action('init', function(){
  if (!isset($_GET['ps_e1e'])) return;
  $f=strtoupper(sanitize_key($_GET['ps_e1e'])); $o=array('v'=>'S1615 e1e','f'=>$f); global $wpdb; $p=$wpdb->prefix; set_time_limit(280);
  $o['temp_istrinta']=(int)$wpdb->query("DELETE FROM {$p}snippets WHERE name LIKE 'TEMP%' AND active=0");
  $J=function($o){ header('Content-Type: application/json'); echo json_encode($o,JSON_UNESCAPED_UNICODE|JSON_PARTIAL_OUTPUT_ON_ERROR); exit; };
  try{
  if($f==='D'){
    $up=wp_upload_dir(); $bk=trailingslashit($up['basedir']).'ps-backups'; wp_mkdir_p($bk);
    $c5='';
    $exp=array(1=>'453fe52c916f61b88b50bb8c5d2b9bfb',2=>'55ae11f2b883d4724e2285ee042109fc',3=>'cbbb1f8e06adc6aa8008a33a1478f3d4',4=>'ea53d0472acab9bb2a9bb5bdf078630a');
