    $o['backup']=copy($t,$bk.'/petshop-darbalaukis-v318-BACKUP-'.date('Y-m-d').'.php');
    $o['rasyta']=file_put_contents($t,$code); $o['po']=md5_file($t); for($i=1;$i<=4;$i++){ @unlink($bk.'/dl-v3181.part'.$i); }
