    $row=function($url,$id) use ($cs){ $r=wp_remote_get($url,array('cookies'=>$cs,'timeout'=>90,'sslverify'=>false)); $h=(string)wp_remote_retrieve_body($r); $out=array('code'=>wp_remote_retrieve_response_code($r),'len'=>strlen($h));
      if(preg_match('/<tr class="eil[^"]*" data-id="'.$id.'"[^>]*>(.*?)<\/tr>/su',$h,$m)){ preg_match_all('/<td[^>]*>(.*?)<\/td>/su',$m[1],$t); $out['td2']=isset($t[1][1])?trim(preg_replace('/\s+/',' ',wp_strip_all_tags($t[1][1]))):null; $out['td2_it']=preg_match_all('/class="dl-it"/',$t[1][1]??''); $out['tr_class']=preg_match('/<tr class="([^"]*)"/',$m[0],$c)?$c[1]:''; $out['pill_r']=strpos($m[1],'dl-note-r')!==false; } else { $out['td2']='EILUTĖS NĖRA'; }
      return $out; };
